script:
// Csillapított rugós rezgés / Damped spring oscillation
//   m·a = −k·x − b·v        f₀ = √(k/m) / 2π        E = ½·k·x² + ½·m·v²
// Az x a nyugalmi helyzettől mért kitérés (lefelé pozitív); a súlyerőt a nyugalmi helyzet már kiegyenlíti.
// x is measured from the rest position (down = positive); gravity is already balanced at the rest position.
stage(1000, 600, "#fbfbf8");
title({hu: "Csillapított rugós rezgés", en: "Damped spring oscillation"});
param("k", {hu: "Rugóállandó k", en: "Spring constant k"}, 5, 100, 40, 1, "N/m");
param("m", {hu: "Tömeg m", en: "Mass m"}, 0.2, 5, 1, 0.1, "kg");
param("b", {hu: "Csillapítás b", en: "Damping b"}, 0, 5, 0.4, 0.05, "kg/s");
param("x0", {hu: "Kezdeti kitérés", en: "Initial displacement"}, -0.5, 0.5, 0.3, 0.01, "m");
resetOn("x0");                                 // új kezdeti kitérés → a mozgás újraindul / new start position → the motion restarts

let x = P.x0, v = 0;                           // kitérés (m, lefelé +) és sebesség (m/s) / displacement (m, down = +) and velocity (m/s)
update(dt => {
  const F = -P.k * x - P.b * v;                // Hooke-törvény + sebességgel arányos csillapítás (N) / Hooke's law + viscous damping
  v += F / P.m * dt;                           // Newton II.: a = F/m
  x += v * dt;
});

draw(t => {
  const kPx = 400;                             // 1 m = 400 px a vásznon / on screen
  const top = 80, rest = 300;                  // a mennyezet y-ja és a test nyugalmi helyzete (px) / ceiling y and rest position
  const y = rest + x * kPx;                    // a test közepe a vásznon / mass centre on the canvas
  rect(380, top - 20, 240, 20, {fill: C.gray, stroke: null});                // mennyezet / ceiling
  spring(500, top, 500, y - 40, {coils: 12, width: 18});
  rect(450, y - 40, 100, 80, {fill: C.blue, radius: 8});
  text("m", 500, y + 7, {size: 22, bold: true, color: "#fff", align: "center"});
  line(600, rest, 680, rest, {stroke: C.gray, dash: [6, 4]});                // nyugalmi helyzet / rest position
  text({hu: "nyugalmi helyzet", en: "rest position"}, 690, rest + 5, {size: 13, color: C.gray});
  const Fs = -P.k * x, Fd = -P.b * v, kF = 15;                                // erők (N); 1 N = 15 px / forces; 1 N = 15 px
  if (abs(Fs) > 0.05) vector(560, y, 0, Fs * kF, {stroke: C.red, lw: 4}, {hu: "F_rugó", en: "F_spring"});
  if (abs(Fd) > 0.05) vector(415, y, 0, Fd * kF, {stroke: C.purple, lw: 4}, {hu: "F_csill", en: "F_damp"});
  show({hu: "Kitérés x", en: "Displacement x"}, x, "m");
  show({hu: "Sebesség v", en: "Velocity v"}, v, "m/s");
  show({hu: "Sajátfrekvencia f₀ = √(k/m)/2π", en: "Natural frequency f₀ = √(k/m)/2π"}, sqrt(P.k / P.m) / (2 * PI), "Hz");
  show({hu: "Energia ½kx² + ½mv²", en: "Energy ½kx² + ½mv²"}, 0.5 * P.k * x * x + 0.5 * P.m * v * v, "J");
  plot("x", x, {unit: "m", color: C.blue});
  plot("v", v, {unit: "m/s", color: C.orange});
});
